Here's a modern data-driven MSTest test class for your `PriceCalculator`:

```csharp
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow for inline compile-time values ---

    [TestMethod]
    [DataRow(10.0, 2, 0.0, 20.0, DisplayName = "No tax")]
    [DataRow(10.0, 3, 0.1, 33.0, DisplayName = "10% tax")]
    [DataRow(5.50, 4, 0.2, 26.40, DisplayName = "20% tax")]
    [DataRow(0.0, 5, 0.1, 0.0, DisplayName = "Zero price")]
    [DataRow(10.0, 0, 0.1, 0.0, DisplayName = "Zero quantity")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        // DataRow doesn't support decimal literals, so cast from double
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- CalculateTotal: DynamicData with ValueTuples for decimal precision ---

    [TestMethod]
    [DynamicData(nameof(CalculateTotalData))]
    public void CalculateTotal_DynamicCases_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal unitPrice, int quantity, decimal taxRate, decimal expected)>
        CalculateTotalData =>
    [
        (100m, 1, 0.07m, 107.00m),
        (29.99m, 3, 0.085m, 97.62m),   // truncation scenario
        (1000m, 10, 0.0m, 10000m),
        (0.01m, 1, 1.0m, 0.02m),       // max tax rate
    ];

    // --- CalculateTotal: invalid inputs throw ---

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, -1, 0.1m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_InvalidTaxRate_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, 1, 1.5m));
    }

    // --- ApplyDiscount: DynamicData with ValueTuples (preferred for decimals) ---

    [TestMethod]
    [DynamicData(nameof(DiscountData))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)>
        DiscountData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),         // no discount
        (80m, 100m, 0m),        // full discount
        (99.99m, 50m, 49.995m), // fractional result
    ];

    // --- ApplyDiscount: invalid discount throws ---

    [TestMethod]
    [DataRow(-1.0)]
    [DataRow(101.0)]
    public void ApplyDiscount_InvalidPercent_Throws(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }
}
```

**Key patterns used:**

| Technique | Why |
|-----------|-----|
| `[DataRow]` | Quick inline cases; note `decimal` isn't a compile-time constant so we use `double` and cast |
| `[DynamicData]` with ValueTuples | Type-safe, supports `decimal` directly, named parameters in the source |
| `Assert.ThrowsExactly<T>` | Modern exception testing (replaces `[ExpectedException]`) |
| `sealed` class | MSTest best practice for performance |
| Constructor init | Enables `readonly` field for the SUT |

For MSTest 3.7+, the ValueTuple `DynamicData` pattern avoids the old `IEnumerable<object[]>` boilerplate entirely.
